import math


class Gradebook:
    def __init__(self) -> None:
        self._assignments = {}
        self._grades = {}

    def add_assignment(
        self, name: str, weight: float, kind: str = "homework"
    ) -> None:
        if name in self._assignments:
            raise ValueError(f"Assignment already exists: {name}")
        if kind not in ("homework", "quiz"):
            raise ValueError("kind must be 'homework' or 'quiz'")
        if not math.isfinite(weight) or weight <= 0:
            raise ValueError("weight must be a positive finite number")
        self._assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self._assignments:
            raise ValueError(f"Unknown assignment: {assignment}")
        if not 2.0 <= grade <= 5.0:
            raise ValueError("grade must be between 2.0 and 5.0")
        self._grades.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        grades = self._grades.get(student, {})
        entries = [
            (name, weight, kind, grades.get(name, 2.0))
            for name, (weight, kind) in self._assignments.items()
        ]

        quizzes = [entry for entry in entries if entry[2] == "quiz"]
        if len(quizzes) > 1:
            lowest = min(quizzes, key=lambda entry: entry[3])
            entries.remove(lowest)

        total_weight = sum(entry[1] for entry in entries)
        if not total_weight:
            raise ValueError("Cannot calculate an average without assignments")

        weighted_sum = sum(weight * grade for _, weight, _, grade in entries)
        return round(weighted_sum / total_weight, 2)
